insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bbed5acf-47e7-481b-a5b7-1d6b9eb91fd9', 'es', 'Antes de acercarte aparece el pensamiento “No le voy a gustar”. ¿Cuál es la mejor reacción?', '["Reconocerlo como miedo automático y acercarte de todos modos", "Rebatirlo enumerando razones por las que podrías gustarle", "Usarlo como motivación para mejorar tu técnica", "Esperar a que el pensamiento pase antes de acercarte"]'::jsonb, 'Ese pensamiento es miedo automático, no una señal para detenerte. Acércate de todos modos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7547b293-5e2d-432b-91d9-4b652d3472a7', 'es', 'Repasas una conversación una y otra vez y construyes una historia crítica sobre ti. ¿Qué deberías notar?', '["Que la historia es una prueba objetiva", "Que debes cortar el repaso de inmediato", "Que tienes que corregir cada defecto que percibes", "Que tu mente rellena los huecos con miedo, no con hechos"]'::jsonb, 'Por defecto, la mente rellena los huecos con miedo; darte cuenta rompe ese patrón.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d5706755-0591-489f-9b13-9ec5811a5057', 'es', 'Después de acercarte, un pensamiento te dice: “Sonaste torpe”. ¿Qué deberías hacer?', '["Aceptarlo como prueba y repasar el momento", "Dejar que defina cómo te ves a ti mismo", "Discutir con el pensamiento para callarlo", "Notarlo como ruido de fondo sin creértelo"]'::jsonb, 'No puedes controlar qué pensamientos aparecen, pero sí si te los crees.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('70a9bde6-01ce-4b79-a9e2-97efa1252a1d', 'es', '¿Qué refleja normalmente un rechazo?', '["Lo cómoda que se siente la otra persona", "Tus errores al expresarte", "Poca atracción", "Un fracaso social"]'::jsonb, 'La mayoría de las retiradas son autoprotección, no un juicio.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4792cc41-039e-460b-9a94-6f1fdb50ceb7', 'es', 'Después de un rechazo, ¿dónde está la verdadera seguridad en ti mismo?', '["En seguir entero aunque no te quieran", "En evitar todo rechazo", "En ganarte la aprobación de todos", "En arreglar cada retirada"]'::jsonb, 'La seguridad en ti mismo es mantenerte firme sin importar cómo reaccionen los demás.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('db69db01-07df-42b3-8e90-41a34457e803', 'es', 'Tras una charla corta, ella se despide con amabilidad. ¿Qué deberías suponer?', '["Que dijiste algo mal y fracasaste", "Que te juzgó y no estuviste a la altura", "Que estaba cuidando su comodidad o su tiempo", "Que tienes que ir tras ella para arreglarlo"]'::jsonb, 'Un rechazo suele ser autoprotección, no un veredicto sobre ti.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e37e687b-c171-4e4a-b17d-9ae50f0a2b9f', 'es', '¿Qué es lo que realmente daña tu seguridad después de un mal momento?', '["La historia que sigues repasando, no el momento en sí", "Cómo lo percibieron los demás y cómo reaccionaron", "Lo grave e incómodo que fue lo que pasó"]'::jsonb, 'El problema no es el momento, sino el recuerdo que sigues repitiendo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43e16323-ce86-4e7f-9c28-27d04a6dcc33', 'es', '¿Qué poder tienes sobre tus experiencias pasadas?', '["Borrarlas por completo", "Evitar cualquier momento incómodo en el futuro", "Hacer que los demás las olviden", "Elegir el significado y la historia que te llevas"]'::jsonb, 'Tu perspectiva la escribes tú; reescríbela para liberarte del ruido negativo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b74e3d6f-b4f5-4f7f-a9fe-edc477912533', 'es', 'Un chico espera a sentirse seguro antes de acercarse. ¿Cuál es el problema?', '["La seguridad nace de las pruebas; esperar la retrasa", "Primero debería trabajar sus creencias internas", "Necesita más preparación mental antes de actuar"]'::jsonb, 'La mente confía en pruebas concretas que vienen de la acción. Primero va el valor, no la seguridad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8219bd4-82ca-488f-a68f-22ee4942c702', 'es', '¿Qué cuenta como prueba de que tu seguridad está creciendo?', '["Hablar a pesar de dudar", "Sostener la mirada un segundo más de lo cómodo", "Esperar a sentirte listo", "Cumplir aunque sería más fácil rendirte"]'::jsonb, 'Las pruebas vienen de actuar a pesar de la incomodidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('12f0ca40-33ce-4e67-bffb-cfc678a28f97', 'es', 'Un chico se acerca a pesar de sus dudas. ¿Qué registra su cerebro?', '["“Lo hice de todos modos” se vuelve prueba de que puede", "“Superé el miedo”, lo que fortalece su resiliencia con el tiempo", "“Fui valiente”, lo que refuerza una imagen positiva de sí mismo", "Todas las anteriores"]'::jsonb, 'Todo esto le beneficia y hace más probable que vuelva a acercarse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b0b79ba6-0f99-427a-8b41-59a2b41ccda1', 'es', '¿Qué predice mejor que alguien mejore sus habilidades sociales?', '["La constancia en la práctica repetida", "El talento natural y la inteligencia social de base", "La calidad de la enseñanza y la mentoría que recibe"]'::jsonb, 'La mejora viene de la práctica acumulada con el tiempo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d3e5a977-5717-4d10-aebd-1477b55d9977', 'es', 'Dos chicos tienen interacciones incómodas. Uno lo vuelve a intentar; el otro se rinde. ¿Qué los diferencia?', '["Uno concluyó que le faltaba práctica; el otro, que le faltaba capacidad", "Uno tiene habilidades sociales naturales; el otro no", "Uno tenía mejores técnicas y bases sobre las que construir"]'::jsonb, 'La diferencia está en la conclusión que sacaron, no en la interacción en sí.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f9d8c142-995d-43f7-81fe-a5b493c6b7af', 'es', '¿Qué creencias reflejan una mentalidad de crecimiento?', '["Las habilidades se pueden mejorar", "El esfuerzo lleva a alguna parte", "Fallar define tu capacidad"]'::jsonb, 'Se sigue aprendiendo cuando uno cree que su capacidad puede crecer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2b35fc5b-fbe7-4df2-9a70-b1ba3a8b77b9', 'es', '¿Por qué evitar actuar hace que el miedo crezca con el tiempo?', '["La seguridad se desvanece", "La memoria exagera", "El riesgo parece mayor", "El cuerpo aprende que evitar es seguro"]'::jsonb, 'Cada vez que evitas algo, refuerzas la respuesta de miedo de tu cuerpo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5ba6899a-7c48-43f0-9751-4de815468a09', 'es', 'Un chico quiere esperar a que se le pase el miedo antes de acercarse. ¿Cuál es el problema?', '["Se perderá el momento ideal para iniciar la conversación", "La próxima vez que lo intente, el miedo volverá más fuerte", "Está dejando que la ansiedad decida por él", "El miedo se disuelve actuando, no esperando a estar listo"]'::jsonb, 'El miedo no desaparece pensando ni con el tiempo; se disuelve con el movimiento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9f9aab5f-516e-467e-859b-ddaecdf461cd', 'es', '¿Qué pasa cuando te acercas a pesar del miedo?', '["El dolor que anticipabas siempre se cumple", "La seguridad exige no tener miedo antes", "El miedo se hace más fuerte con la exposición", "Tu sistema nervioso registra que la amenaza era falsa"]'::jsonb, 'La acción desmiente la predicción y suaviza tus respuestas futuras.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5ce08bb8-9bb3-4d2e-b08c-7b62c8593bb1', 'es', '¿Por qué sentirte observado se siente más intenso de lo que realmente es?', '["La gente de verdad te observa con atención", "El juicio es constante", "La mente exagera la atención que hay sobre uno mismo", "Las reglas sociales son estrictas"]'::jsonb, 'La mente sobrestima cuánto se fijan los demás.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5ef57991-7795-4349-9a51-3c0db95233c6', 'es', 'En una conversación de grupo, la atención se centra en ti. ¿Qué deberías hacer?', '["Mantenerte relajado y seguir con naturalidad", "Encerrarte en ti mismo y vigilarte", "Forzar seguridad para ocultar la tensión", "Salir rápido de la conversación"]'::jsonb, 'El aplomo viene de dejarte ver sin resistirte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39115a96-71ac-4675-991c-cb9189cd877a', 'es', '¿Cómo afecta a tu presencia estar vigilándote?', '["Refuerza una conexión auténtica", "Te saca de expresarte y te pone a actuar", "Dirige tu atención hacia dentro en vez de hacia fuera"]'::jsonb, 'Vigilarte socava tu aplomo y tu naturalidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28ccfdfd-13b7-4bf5-9d16-e2ade47fa571', 'es', '¿Qué le indica al cuerpo una respiración superficial?', '["Seguridad", "Amenaza", "Concentración", "Confianza"]'::jsonb, 'Respirar rápido le indica peligro al cuerpo. Respira más lento para calmarte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('784400be-2ea4-4606-85a5-fb25457e3b9c', 'es', 'La presión sube y tu mente se acelera antes de hablar. ¿Qué te ayudaría?', '["Ensayar las palabras mentalmente", "Evitar la situación hasta estar tranquilo", "Una inhalación pausada y una exhalación controlada"]'::jsonb, 'Prestar atención a la respiración le recuerda a tu cuerpo que tú tienes el control.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7a7a2960-2b38-4259-9599-598cc15e9937', 'es', '¿Por qué respirar despacio reduce el miedo con eficacia?', '["Rebate directamente los pensamientos negativos", "Le indica seguridad al sistema nervioso", "Baja el ritmo cardíaco y despeja la mente"]'::jsonb, 'Alargar la exhalación le dice a tu sistema nervioso que no hay ninguna amenaza que resolver.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('013f4dc3-e950-4940-9fab-7657d9decb9b', 'es', '¿Cómo interrumpe el anclaje los pensamientos en espiral?', '["Cambiando el significado", "Llevando la atención a las sensaciones", "Aumentando la concentración", "Reprimiendo las emociones"]'::jsonb, 'El anclaje funciona sacando la atención de la mente y llevándola a las sensaciones físicas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('81883b1d-a00d-4283-b3fc-38c0192aaff9', 'es', '¿Dónde vive la ansiedad y cómo ayuda el anclaje?', '["La ansiedad vive en traumas pasados; el anclaje crea experiencias nuevas", "La ansiedad vive en el cuerpo; el anclaje libera la tensión física", "La ansiedad vive en pensamientos sobre el futuro; el anclaje te devuelve al presente"]'::jsonb, 'La ansiedad vive en pensamientos sobre el futuro; el anclaje devuelve la atención al cuerpo, en el presente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b700e82d-a04f-4ae2-af7e-9af63595b855', 'es', '¿Qué acciones de anclaje ayudan a reducir la ansiedad?', '["Sentir los pies en el suelo", "Notar el movimiento de la respiración", "Planear frases para la conversación", "Relajar los hombros"]'::jsonb, 'El anclaje funciona sacando la atención de la mente y llevándola a las sensaciones físicas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4cdb8cfc-39c3-4aee-8e46-064ef4dd4976', 'es', 'Mientras estás de pie hablando con ella, te sientes rígido. ¿Qué ayuda más?', '["Inclinarte hacia delante", "Hablar más despacio", "Hacer bromas", "Relajar los hombros y la respiración"]'::jsonb, 'Soltar primero el cuerpo te devuelve una presencia natural durante la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('35629852-7dc2-4adf-8383-df72ab56b0fb', 'es', '¿Qué relación hay entre el lenguaje corporal y la confianza?', '["Un lenguaje corporal coherente en el tiempo genera confianza", "La gente confía más en lo que ve que en lo que oye", "Las personas confiables muestran naturalmente un lenguaje corporal abierto y relajado"]'::jsonb, 'La gente reacciona a las señales no verbales antes de escuchar explicaciones.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('be052099-dc33-4516-be7b-fb7e8a574364', 'es', '¿Por qué el lenguaje corporal habla antes que las palabras?', '["El cerebro lee primero el movimiento y la postura en busca de seguridad", "La gente procesa las señales no verbales más rápido que las verbales", "Cuando el cuerpo y las palabras no coinciden, se siente una desconexión", "Las palabras siempre se imponen a las señales físicas"]'::jsonb, 'Lo no verbal se procesa por instinto, antes que la lógica.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('32686574-8a7a-4a9b-8887-1bf18793907c', 'es', '¿Cómo capta realmente la gente las señales de tu tono de voz?', '["Si suenas tenso, se sienten tensos; si suenas tranquilo, se sienten tranquilos", "Notan y evalúan de forma consciente tu estado emocional", "Los patrones de la voz activan neuronas espejo que generan empatía"]'::jsonb, 'La gente imita sin darse cuenta la energía de tu voz. Mantenla tranquila.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('82c30e7d-5adc-41dc-afc4-5569d6e8fb80', 'es', '¿Qué patrones de voz ayudan a que los demás se sientan a gusto?', '["Un ritmo más lento", "Hablar al exhalar", "Llenar rápido los silencios", "Un volumen estable"]'::jsonb, 'Un ritmo pausado y una buena respiración hacen que tu voz se sienta segura y agradable de escuchar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5cdfce0f-0fe8-4f05-b355-7b070e7383bd', 'es', '¿Por qué una voz tranquila influye más en la gente que una voz fuerte?', '["Exige atención con el volumen", "Transmite seguridad y calma de forma inconsciente", "Hace que la gente escuche sin forzarla", "Crea peso y un ritmo relajado"]'::jsonb, 'Un tono tranquilo atrae a la gente porque transmite estabilidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6cd4ab05-6a0e-4e05-9ef2-09775c5c9496', 'es', '¿Por qué la energía baja puede alejar a los demás?', '["Resulta incómodo reflejarla", "Transmite arrogancia", "Da a entender desinterés"]'::jsonb, 'La gente evita por instinto los estados que se sienten pesados. Mantén tu energía positiva.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e40cadb9-6906-42bf-b334-b269e634ab6e', 'es', '¿Cómo puedes subir tu energía antes de acercarte?', '["Mover un poco el cuerpo, sonreír y darte ánimo", "Analizar la situación más tiempo", "Esperar a que aparezca la seguridad", "Retirarte para evitar la tensión"]'::jsonb, 'El movimiento físico cambia rápido tu estado y sube tu energía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d028ed4f-fd88-4a7c-8aab-17f7a78c6a9a', 'es', '¿Cómo influye la energía positiva en tus acercamientos?', '["Atrae a la gente de forma inconsciente", "Invita a interactuar con naturalidad", "Exige una apariencia perfecta"]'::jsonb, 'La buena energía hace que la gente se acerque y se sienta mejor contigo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('55639c7a-b396-4a1c-ae26-431442cfe270', 'es', '¿Qué transmite primero una sonrisa genuina?', '["Atracción", "Seguridad en ti mismo", "Confianza y calidez", "Ganas de jugar"]'::jsonb, 'Una sonrisa se lee al instante como señal de que eres de fiar. Te ayuda antes de decir una palabra.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cfa95ebd-1b35-41c8-8a50-fbcb06fee6aa', 'es', '¿Por qué sonreír reduce la tensión social?', '["Desvía la atención", "Activa respuestas emocionales positivas", "Oculta los nervios"]'::jsonb, 'Cuando sonríes, los dos cerebros registran algo positivo antes de intercambiar palabras.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2886592f-4bba-4b7d-bcfc-6547f1eb778e', 'es', '¿Cómo genera una sonrisa genuina una respuesta positiva en las dos personas?', '["Le señala una amenaza al sistema nervioso", "Mejora el ánimo y reduce el estrés a nivel neurológico", "El cerebro imita la emoción positiva de forma inconsciente"]'::jsonb, 'Sonreír despierta sentimientos positivos en ambos antes de que empiece la conversación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2c9f06f7-4cf4-45f9-80cd-7c8fcac8c28c', 'es', '¿Por qué depender de la aprobación debilita tu seguridad?', '["Genera presión", "Limita tu forma de expresarte", "Transmite inseguridad", "Debilita tus límites"]'::jsonb, 'Necesitar aprobación comunica que no te validas a ti mismo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7bd56cd8-1f4f-4678-8dce-d3e92a3e8932', 'es', 'Ella da una opinión con la que no estás de acuerdo. ¿Qué evita que busques su aprobación?', '["Darle la razón de inmediato para mantener la armonía", "Compartir con educación tu punto de vista, sin disculparte", "Cambiar tu opinión para que coincida con la suya", "Quedarte callado para evitar el conflicto"]'::jsonb, 'Mantener tu actitud con calma transmite que te aceptas a ti mismo, sin necesidad de su aprobación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3fe6a5a2-4f72-4f9a-9d46-3a48ef587e96', 'es', '¿Por qué buscar aprobación espanta la atracción?', '["Transmite desesperación por ser validado", "Hace que tu valor dependa de que ella te acepte", "Te hace parecer poco auténtico", "Siempre garantiza una conexión más profunda"]'::jsonb, 'Buscar aprobación transmite inseguridad; aceptarte a ti mismo transmite fuerza.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e562de05-8b81-429d-b188-fbe14cf83db2', 'es', 'Un chico sigue sintiéndose nervioso después de meses de práctica. ¿Qué debería medir?', '["Si otros avanzan más rápido con un tiempo de práctica parecido", "Si ahora puede hacer cosas que antes no podía", "Cómo se compara su nivel con el de hombres seguros por naturaleza"]'::jsonb, 'La única medida que importa es si eres mejor que antes.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('586652d7-39f3-41aa-9a2f-cb693ae30050', 'es', '¿Por qué compararte con otros perjudica el desarrollo de tus habilidades?', '["No sabes de dónde partieron, cuánto practicaron ni su historia completa", "Crea expectativas poco realistas que garantizan el fracaso", "Comparas lo que vives por dentro con resultados ajenos, y eso no es justo"]'::jsonb, 'Ves sus resultados sin saber de dónde partieron ni cuál es su historia.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9250aace-fa4f-4d66-95e4-793349439200', 'es', '¿Qué hace que acercarte se sienta más ligero?', '["No dejar que el resultado defina quién eres", "Aceptar el rechazo como parte normal del proceso", "Las dos anteriores"]'::jsonb, 'Cuando el resultado no determina tu valor, acercarte intimida menos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('53bacb30-3d41-4c17-a18d-8c00b9bc1398', 'es', '¿Qué significa no depender del resultado en tus interacciones?', '["Mantener el equilibrio emocional sin importar su respuesta", "Que los resultados no te importen en absoluto", "Forzar un buen resultado cada vez", "Evitar interacciones para estar a salvo"]'::jsonb, 'Cuando tu ánimo se mantiene estable sin importar la respuesta, recuperas el control.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('83794883-664e-42e0-89fa-abc8d0f95334', 'es', '¿Qué significa realmente no depender del resultado?', '["Que no te importen en absoluto los resultados ni el éxito de tus interacciones", "Mantener el equilibrio emocional sin importar cómo vayan las interacciones", "Que tu valor propio y tu ánimo no estén atados a resultados concretos"]'::jsonb, 'Los resultados te siguen importando, pero ya no dictan cómo te sientes ni cómo actúas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39d1a173-8185-476b-ba48-a86f79e52a48', 'es', '¿Cuál es la clave para manejar bien una respuesta positiva?', '["Esforzarte más para mantener su atención", "Bajar tu energía para no presionar", "Controlar el momento para no perderlo", "Seguir siendo la misma versión de ti que despertó su interés"]'::jsonb, 'La versión de ti que generó la atracción ya es suficiente. No intentes mejorarla ni actuar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b61bcf4-54dc-4de9-8ba8-813071e2e979', 'es', 'La vibra es buenísima y ella se inclina hacia ti. Tu mente empieza a planear “qué sigue”. ¿Qué deberías hacer?', '["Volver a estar presente sin intentar controlar", "Dejar que los pensamientos tomen el mando para planear", "Avanzar rápido para aprovechar el momento", "Alejarte de la energía positiva"]'::jsonb, 'Cuando las cosas van bien, tu trabajo es mantener el ritmo, no manejar el resultado.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0b5dc6ef-1cda-498e-932d-4939839666ad', 'es', '¿Por qué una respuesta positiva puede desestabilizarte?', '["Despierta la búsqueda de validación desde una mentalidad de escasez", "Activa el miedo a perder esa buena sensación", "No exige ningún cambio en tu comportamiento", "Puede generar presión por aprovecharla y controlarla"]'::jsonb, 'Las señales positivas traen algo que perder; evita pasar a proteger el resultado.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5956bc0c-e67e-486c-9121-0d4f3f555035', 'es', '¿Qué cambia primero el ejercicio físico, antes de que los demás noten tu cuerpo?', '["Tus conocimientos de entrenamiento y tu disciplina", "Cómo te ves a ti mismo y tu seguridad interior", "Tu capacidad para llamar la atención", "Tu forma de conversar y tu encanto"]'::jsonb, 'La seguridad crece cuando primero mejora la imagen que tienes de ti mismo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9ec8b2af-94c5-4b1c-a704-f2bd3e950b20', 'es', '¿Cómo te ayuda estar en forma a tener más seguridad?', '["Es una prueba física de que te tomas en serio", "Te hace visiblemente atractivo para las mujeres", "Te enseña una disciplina que se traslada a las citas", "Te da estatus en situaciones sociales"]'::jsonb, 'Estar en forma cambia primero cómo te ves a ti mismo, y eso hace más probable que te acerques.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d0c9fead-d08c-463e-82b3-6acbc68aa42b', 'es', '¿Qué produce el cambio de seguridad que da estar en buena forma?', '["Creer que tu cuerpo es más capaz", "Ver en el espejo un cuerpo que respetas", "Vigilarte menos en situaciones sociales", "Recibir halagos de los demás"]'::jsonb, 'El respeto por ti mismo moldea tu comportamiento mucho antes de que importe la validación externa.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('941578b4-3efd-48fd-bb43-567d6cc34570', 'es', '¿Cómo afecta un mal arreglo personal a la primera impresión?', '["Las mujeres esperan más esfuerzo", "Transmite bajo estatus", "Genera dudas tempranas antes de que surja la atracción"]'::jsonb, 'Las primeras señales visuales moldean la comodidad y el interés antes de que empiece la conversación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('320c1b55-513d-40ef-8b8a-5575836c5e6c', 'es', '¿Cuál es el principal efecto interno de mantener un buen arreglo personal?', '["La validación externa de los halagos", "Forzar la seguridad a base de fuerza de voluntad", "Un cambio drástico en tus rasgos físicos", "Sentirte impecable y arreglado sin esfuerzo"]'::jsonb, 'El arreglo personal cambia cómo te ves a ti mismo, y eso hace más probable que te acerques.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c8f3b672-a516-497b-889c-0bb6535c7859', 'es', '¿Qué beneficios tiene el arreglo personal?', '["Mejores primeras impresiones", "Menos barreras internas, así que te comportas con naturalidad", "Le muestra respeto por ti mismo a una posible pareja", "Te da ventaja sobre hombres menos arreglados"]'::jsonb, 'Primeras impresiones más limpias, un comportamiento más libre y un respeto por ti mismo que se nota.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e694c46-0fd5-4820-84c0-2432a8fd7227', 'es', '¿Cómo te ayudan unos buenos hábitos de higiene a la hora de acercarte?', '["Eliminan pequeñas barreras que estorban a la atracción", "Transmiten que te importan los demás", "Te aseguran oler mejor que otros hombres", "Crean siempre una primera impresión impecable"]'::jsonb, 'La higiene elimina roces invisibles que generan distancia.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d0aa5e3a-b58e-4eea-8381-e21cbca6f874', 'es', '¿Qué te aporta realmente cuidar tu higiene?', '["Quita barreras que impiden que surja la atracción", "Te da la tranquilidad interna para estar más cerca", "Te hace más encantador y hábil en lo social"]'::jsonb, 'Saber que tu higiene está en orden elimina la necesidad de vigilarte y las barreras invisibles que generan roces.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9b201136-be01-4de3-b7a9-41ab4fa02a38', 'es', '¿Por qué vestir con poco estilo crea un roce invisible?', '["Corta el flujo de la conversación", "Te quita seguridad al hablar", "Influye negativamente en los primeros juicios", "Transmite introversión"]'::jsonb, 'Los primeros juicios influyen en lo abierta que está la otra persona antes de que la interacción empiece de verdad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3ef8c23-3bd4-42a1-ba4a-0cc007c4f952', 'es', '¿Cómo influye vestir con buen estilo en tu seguridad interior?', '["Mejora tu sentido del humor", "Aumenta tu dominancia", "Te distrae menos de ti mismo", "Hace que te vigiles menos"]'::jsonb, 'Ropa que te queda bien y es cómoda mantiene tu atención hacia fuera, no hacia dentro.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('02e91b80-7376-4e58-a593-604cc6b23a79', 'es', 'Tu risa suena forzada y tu voz, aguda. ¿Qué práctica te ayuda?', '["Hablar más fuerte al inhalar", "Subir el tono para atraer", "Darte un momento antes de pensar y hablar al exhalar", "Acelerar para ir al ritmo de los nervios"]'::jsonb, 'Un ritmo controlado al exhalar estabiliza tu tono y tu presencia.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('03af7107-7650-4d54-b1a7-e9dee067e1b1', 'es', 'Cuando alguien empieza a vigilarse a sí mismo, ¿qué cambia en la interacción?', '["La actuación sustituye a la conexión", "Se expresa menos", "La ansiedad desaparece"]'::jsonb, 'Vigilarte aleja tu atención de la interacción genuina.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0cfb0ca8-28d9-426f-80c4-d26b972acc51', 'es', 'Un chico repasa una conversación y concluye que sonó torpe. ¿Qué está pasando?', '["Está aprendiendo de sus errores para mejorar la próxima vez", "Está siendo realista sobre su desempeño social", "Su mente rellena los huecos con miedo, no con hechos", "Su autoconciencia le ayuda a identificar puntos débiles"]'::jsonb, 'La historia que te cuenta tu mente después no es un relato fiable de lo que pasó.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1050b192-a012-4512-86fb-9ceb4d8087e7', 'es', '¿Qué efectos puede tener una sonrisa genuina?', '["Menos estrés", "Pareces más accesible", "La otra persona baja la guardia", "Atracción inmediata"]'::jsonb, 'Una sonrisa genuina transmite calidez antes de que empiece la conversación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1078c50b-deac-4399-9cc9-3872de90104c', 'es', '¿Cuál es el cambio de fondo detrás de la seguridad en ti mismo?', '["Que te admiren", "Impresionar", "Que te acepten", "No necesitar demostrar nada"]'::jsonb, 'La seguridad se estabiliza cuando tu valor ya no depende de los demás.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1d689f0a-9831-4f51-86c0-26f91d7c3192', 'es', '¿Por qué el anclaje reduce la ansiedad antes de acercarte?', '["Distrae a tu mente de los pensamientos ansiosos por un rato", "Las sensaciones físicas indican seguridad y desactivan la respuesta de amenaza", "Concentrarte en tu cuerpo te da seguridad a través de la conciencia"]'::jsonb, 'El anclaje funciona sacando la atención de la mente y llevándola a las sensaciones físicas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('219e0cdc-a9ad-455f-86bd-5424943faf26', 'es', 'Un chico recibe una señal de aprobación y enseguida piensa: “No lo arruines”. ¿Qué pasa?', '["La presión le ayuda a evitar errores", "Crea una presión que cambia su energía", "El pensamiento lo motiva a seguir metido en la conversación"]'::jsonb, 'Intentar no fallar sustituye a una participación relajada y daña la conexión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('259c1e7d-ff03-4cbb-8e6f-491608175612', 'es', '¿Qué hace realmente la energía positiva?', '["Atrae a la gente porque se siente mejor contigo", "Genera atracción inmediata con señales de alto estatus", "Hace que tus palabras sean más persuasivas", "Facilita que la gente interactúe contigo"]'::jsonb, 'La energía positiva hace que la gente se sienta bien, y eso la atrae de forma natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2aba3577-76b4-423a-898b-cb6e1f03d88d', 'es', 'Un chico habla rápido y con la voz aguda mientras se acerca. ¿Qué está pasando?', '["Su emoción se percibe como energía nerviosa", "Su tono transmite tensión, y ella la siente antes de oír sus palabras", "Sin darse cuenta, intenta llenar los silencios y mantener el ritmo"]'::jsonb, 'Cuando el tono suena acelerado o forzado, la gente siente tensión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('35e59aa9-31b1-4b02-af42-50fe8b4a375c', 'es', 'Un chico elige mal las palabras, pero tiene muy buena energía. ¿Qué pasa?', '["La interacción se siente bien de todos modos", "La conversación fracasa", "El interés cae rápido", "La gente se fija en sus errores"]'::jsonb, 'Cuando tu energía es positiva, a la gente le gusta estar contigo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('40266254-315c-41fe-9eba-7ad6413d86a3', 'es', '¿Por qué al principio sonreír funciona mejor que las palabras?', '["Las palabras se sienten arriesgadas", "Las caras se procesan más rápido", "Una sonrisa muestra tu intención con claridad", "El silencio transmite seguridad"]'::jsonb, 'El cerebro lee las caras antes que el lenguaje. Sonríe primero y deja que te ayude.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43d2d9f6-2ffb-4330-8584-9a58b70d6399', 'es', '¿Por qué estar en forma da seguridad más allá de la apariencia?', '["Cambia de inmediato cómo te perciben los demás", "Mejora cómo te ves a ti mismo y el respeto por tu cuerpo", "Reduce la autovigilancia y las dudas internas"]'::jsonb, 'Estar en forma moldea lo que crees de ti y reduce el ruido, lo que refuerza tu seguridad natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('46eb84b4-53da-484e-8846-fdb26ae3c785', 'es', '¿Qué fortalece tu seguridad a largo plazo?', '["Emociones tranquilas", "Planes claros", "Evitar la incomodidad", "Actuar a pesar del miedo"]'::jsonb, 'La seguridad se forma después de dar la cara, no antes.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4ac6998e-65dd-431c-99de-be7a3f97072e', 'es', 'Mientras te acercas, se te tensan los hombros y la mirada se te va de un lado a otro. ¿Qué deberías priorizar?', '["Quitar las señales de tensión relajando la postura y la respiración", "Hablar más rápido para tapar los nervios", "Forzar un contacto visual más intenso", "Hacer gestos más grandes para parecer seguro"]'::jsonb, 'Tu cuerpo transmite seguridad o tensión antes de que lleguen tus palabras.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51ceb33f-6d3d-4110-8369-52ab53cc3b2c', 'es', 'Ella muestra mucho interés y sientes la urgencia de “no arruinarlo”. ¿Qué mentalidad te ayuda?', '["Esta oportunidad es rara y tengo que asegurarla", "Echarme para atrás para ir a lo seguro", "Subir la intensidad para merecer el momento", "Su interés es agradable; sigue siendo quien la atrajo"]'::jsonb, 'Reconoce su interés sin aferrarte a él ni ir tras más.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5423b03c-3be1-4925-81c1-77d8776ea860', 'es', 'Caminas hacia ella después de cruzar miradas. ¿Qué expresión ayuda más?', '["Cara neutra y seria", "Una gran sonrisa forzada", "Una sonrisa cálida y genuina que mantienes", "Ninguna expresión, para parecer tranquilo"]'::jsonb, 'Una sonrisa genuina transmite confianza antes de intercambiar palabras.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59af149f-a4e1-4e59-9e5c-79c015952617', 'es', 'Una interacción sale mal. ¿Qué deberías pensar?', '["“Eso no funcionó. ¿Qué puedo ajustar la próxima vez?”", "“Soy malo para esto, en el fondo.”", "“Algunos nacen con el don; yo no.”", "“Debería dejar de intentarlo.”"]'::jsonb, 'La mentalidad de crecimiento convierte el rechazo en información para mejorar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6050d9fa-5758-4a66-9d2a-4484751813c5', 'es', 'Un chico intenta controlar cómo se ve mientras recibe atención. ¿Qué precio paga?', '["Parece menos seguro y más cohibido", "La gente nota la actuación y reacciona mal", "Controlar su imagen lo hace menos auténtico y más actuado"]'::jsonb, 'Cuanto más intentas controlar cómo te ves, menos auténtico eres.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('695eb047-3678-474b-a13a-26682bf11d5f', 'es', 'Entras a un lugar con los brazos cruzados y poca energía. ¿Qué pasa después?', '["La gente se acerca a ti con ganas", "Te vas sintiendo más relajado", "La gente te evita sin darse cuenta", "Tus palabras tienen más peso"]'::jsonb, 'Un lenguaje corporal cerrado transmite retirada, aunque quieras conectar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6e9907b3-8130-4125-a5aa-e6b1a0898b60', 'es', '¿Qué determina que mejores tus habilidades sociales a largo plazo?', '["Tener talento natural desde el principio", "Creer que las habilidades se desarrollan con la práctica", "Seguir esforzándote a pesar de los tropiezos", "Evitar los retos para proteger tu seguridad"]'::jsonb, 'Las habilidades solo se desarrollan si no te rindes y sigues adelante.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7ea9a0ee-49fd-4682-8888-bb7fba4dfa72', 'es', 'A mitad de la charla, sigues con los brazos cruzados y la postura caída. ¿Qué transmite esto?', '["Una incomodidad que te encierra, digas lo que digas", "Una presencia fuerte y segura", "Una energía relajada y tranquila", "Un aire misterioso a propósito"]'::jsonb, 'Un cuerpo tenso contradice la soltura de tus palabras y crea desconexión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7f2e5b24-f05e-439d-9f03-8ea8d846f05a', 'es', 'Antes de entrar a un lugar te sientes con poca energía. ¿Qué podría reactivarla?', '["Quedarte en una esquina hasta sentirte mejor", "Forzarte a hablar más fuerte", "Mover el cuerpo y sonreír a propósito", "Evitar interactuar hasta que salga natural"]'::jsonb, 'Pequeñas acciones cambian tu energía y la vuelven positiva y acogedora.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('80156644-8f30-46b7-9f70-3e7b0fbd786f', 'es', 'Se te aprieta el pecho y la mente se te acelera mientras te preparas para hablar. ¿Qué técnicas de anclaje ayudan?', '["Pensar una y otra vez en resultados positivos", "Forzar temas de conversación más profundos", "Evitar la situación hasta estar más tranquilo", "Sentir los pies en el suelo y respirar más lento"]'::jsonb, 'El anclaje funciona porque lleva tu atención de los pensamientos sobre el futuro a las sensaciones del presente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('82bb1ff8-f12d-487b-9b54-090588f0d69d', 'es', '¿Por qué una respuesta positiva a veces dispara más adrenalina que un rechazo?', '["El éxito es, por naturaleza, más intenso emocionalmente que el fracaso", "El sistema nervioso reacciona más fuerte a las recompensas que a las amenazas", "Crea un miedo nuevo: el miedo a perder la oportunidad"]'::jsonb, 'Las señales positivas traen algo que perder; evita pasar a proteger el resultado.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8a5e8c45-7476-413e-8358-7c92cdbab538', 'es', '¿Qué debilita el miedo con el tiempo?', '["Hablarte en positivo antes de los momentos de presión", "Actuar a pesar de la señal, lo que actualiza el sistema", "Cada acercamiento que no termina en el dolor que temías", "El movimiento, más que pensar o prepararte mentalmente"]'::jsonb, 'El miedo se suaviza cuando la acción demuestra que sus predicciones eran falsas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8dc6c797-1c0b-443d-ab04-062afc92c412', 'es', '¿Qué pasa cuando dejas de necesitar aprobación?', '["Tu seguridad se vuelve más estable", "Recibes menos atención", "Las interacciones se acortan", "Pierdes el control"]'::jsonb, 'Tu valor no depende de la validación externa.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8f1849bb-0b9f-4680-afff-7f0d273e5810', 'es', '¿Qué señales físicas influyen en la primera impresión?', '["La mirada", "Los pensamientos internos", "La postura"]'::jsonb, 'Las señales visibles moldean la percepción al instante.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94983000-db09-40ee-ac8e-75de9d87d3f6', 'es', '¿Qué pasa cuando actúas a pesar del miedo?', '["La duda crece por falta de acción", "El cerebro aprende que el miedo no es definitivo", "La creencia se fortalece con la exposición", "La seguridad se forma al hacerlo de todos modos"]'::jsonb, 'Salir bien parado una y otra vez le da a tu mente pruebas fiables.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9c28c269-1ab6-4f2a-9043-22fadc730b6b', 'es', 'Dudas en acercarte, pero lo haces de todos modos y no pasa nada malo. ¿Qué logra esto?', '["Una pequeña prueba que tu cerebro guarda para confiar en el futuro", "Una seguridad perfecta e inmediata", "Solo un alivio pasajero"]'::jsonb, 'Cada vez que actúas de todos modos, sumas a un historial en el que puedes confiar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a0b5f46b-7b16-4682-b089-7e8d882d5dea', 'es', '¿Cómo le ayuda sonreír a la persona que sonríe?', '["Mejora su postura", "Libera sustancias químicas que calman", "Aumenta su dominancia"]'::jsonb, 'Sonreír cambia tu estado interno al liberar sustancias en el cerebro. Sonríe más.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a7253e20-5530-468a-a086-0f0e27b02b4b', 'es', '¿Por qué evitar las situaciones aumenta el miedo con el tiempo?', '["Le enseña al cuerpo que evitar es más seguro", "Refuerza la respuesta de miedo al no exponerte", "Te da seguridad poco a poco"]'::jsonb, 'Echarte para atrás refuerza el ciclo de evitación y la señal de miedo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b400f47c-56f1-455f-8258-5bf582c021f8', 'es', 'Estás nervioso, pero quieres parecer relajado. ¿Qué alinea tu cuerpo con tu intención?', '["Mantenerte erguido, respirar a fondo y no interrumpirte a ti mismo", "Cruzar los brazos para protegerte", "Evitar el contacto visual para bajar la presión", "Moverte inquieto para soltar energía"]'::jsonb, 'Un cuerpo abierto y estable refleja calma sin actuar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b505f110-e322-4bf1-9300-fb0cc533a552', 'es', 'Te surge una duda: “No le voy a gustar”. ¿Qué deberías hacer?', '["Reconocerla como ruido y dejarla pasar sin creértela", "Pelear con la duda para demostrar que es falsa", "Creértela para ser realista", "Repasarla para analizarla a fondo"]'::jsonb, 'No puedes controlar qué pensamientos aparecen, pero sí si te los crees.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8441682-aa6b-4a9b-b7ac-97e0f2c1573d', 'es', '¿Por qué la energía positiva atrae a la gente a interactuar?', '["La gente se siente mejor cerca de ella", "Transmite dominancia", "Exige atención"]'::jsonb, 'Los estados agradables acercan a la gente de forma natural. Mantén tu energía positiva.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8999272-dae6-4926-b567-a975478a321d', 'es', '¿Qué rompe la conexión antes incluso de que empiece la conversación?', '["Una mirada esquiva y una postura cerrada que transmiten inseguridad", "Un cuerpo tenso que transmite incomodidad aunque tus palabras suenen relajadas", "Usar la frase de apertura equivocada o una mala técnica"]'::jsonb, 'Las señales físicas de incomodidad rompen la conexión, digas lo que digas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c5d60b8c-c34d-4089-81c4-a5f56034f361', 'es', 'Entras a un lugar lleno de gente y sientes todas las miradas sobre ti. ¿Qué deberías recordarte?', '["Que todos te están juzgando con dureza", "Que tienes que hacerlo todo perfecto para encajar", "Que la mayoría está pendiente de sí misma, no de ti", "Que es mejor esconderte hasta que se te pase"]'::jsonb, 'La mente exagera la atención que recibes; en realidad, nadie está tan pendiente de ti.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c8828ffa-d37b-4033-9da0-bd56a61641e5', 'es', 'La conversación fluye a la perfección y ella muestra un interés claro. ¿Qué deberías evitar?', '["Seguir con naturalidad en el momento", "Responder a sus señales positivas", "Dejar que el ritmo respire", "Esforzarte más para conseguir más aprobación"]'::jsonb, 'La presión por buscar aprobación rompe el flujo natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c918a4eb-10ec-4f35-a8de-8627f329a218', 'es', 'A mitad de la conversación sientes el pecho apretado y la respiración superficial. ¿En qué deberías concentrarte?', '["Forzar tu voz para que suene tranquila", "Volver a una respiración pausada y controlada", "Terminar la interacción para recuperarte", "Hablar más rápido para acabar pronto"]'::jsonb, 'Regular la respiración estabiliza tu voz antes de que intentes estabilizar tus palabras.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc39682a-160f-459c-a7c6-83758e6a8ad3', 'es', '¿Cuál es el principal beneficio de entrenar con constancia?', '["Una apariencia perfecta para la validación externa", "Mejoran cómo te ves a ti mismo y tu seguridad interior", "Cambios drásticos e inmediatos en tu aspecto", "Forzar la seguridad a base de fuerza de voluntad"]'::jsonb, 'Un cuerpo que respetas te da, desde dentro, una seguridad que no cuesta esfuerzo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e0b7ae70-05c8-4c9c-8a5b-c48a3e0f6743', 'es', 'Tu cuerpo se tensa antes de acercarte a alguien. ¿Qué significa esto?', '["Biología y una oportunidad para crecer", "Debilidad y un motivo para detenerte", "Un mal resultado asegurado", "Que nunca vas a estar listo"]'::jsonb, 'El miedo es una respuesta fisiológica normal, no una señal de alto. Moverte demuestra que se equivoca.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e172e286-a34d-4fba-a51e-7a29d03e5107', 'es', 'Ella se ríe con facilidad, se acerca más y te toca el brazo. ¿Qué deberías hacer?', '["Subir la energía y esforzarte más por impresionarla", "Empezar a pensar qué decir para que todo siga perfecto", "Mantenerte relajado y seguir como ibas", "Avanzar de inmediato para concretar"]'::jsonb, 'Su interés no es una señal para esforzarte más; es una señal para seguir igual.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e56ee826-cd5b-4fb6-8005-84e669a0b1d7', 'es', '¿Por qué respirar ayuda cuando aparece el miedo antes de acercarte?', '["Te distrae del miedo", "Hace más lento el momento", "Te da seguridad al instante", "Le indica seguridad al sistema nervioso"]'::jsonb, 'Respirar despacio le dice al cuerpo que está a salvo y calma tu estado antes de actuar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e750c943-9bb0-4a66-892d-3442f22cd528', 'es', '¿Por qué el encanto puede fallar cuando el cuerpo está tenso?', '["La atracción se esfuma rápido", "Las palabras pierden sentido", "El momento no se siente bien", "Las señales visuales pesan más que lo que dices"]'::jsonb, 'El cerebro confía en lo que ve, no en lo que oye.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e9e55ffe-f94e-4155-a34b-977fd5d465ba', 'es', '¿Cómo se construye principalmente la seguridad en uno mismo?', '["Con pensamiento positivo y palabras de ánimo", "Con rasgos naturales de personalidad", "Acumulando pruebas a través de acciones repetidas", "Evitando riesgos hasta estar listo"]'::jsonb, 'La seguridad crece con pruebas de que sobreviviste a lo que hiciste, no con la imaginación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ec90b480-b289-4b95-82b0-39d6020cb7dc', 'es', '¿Qué diferencia a los hombres seguros por naturaleza de los que dudan?', '["Los hombres seguros han acumulado más pruebas a base de repetir", "Los rasgos de personalidad determinan el nivel básico de seguridad", "Los hombres seguros aprendieron antes a creer en sí mismos"]'::jsonb, 'La diferencia son las pruebas acumuladas: uno tiene pruebas en las que puede confiar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f030a547-86d7-4259-a4ec-1734e65a10e0', 'es', 'Una conversación se estanca y se siente incómoda. ¿Qué deberías pensar?', '["“Nunca voy a mejorar en esto.”", "“Fallar significa que algo está mal en mí.”", "“Esto no es para mí.”", "“Esto es información. ¿Qué puedo ajustar la próxima vez?”"]'::jsonb, 'Con mentalidad de crecimiento, los tropiezos se pueden ajustar y sigues participando.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f41af47d-77fc-439e-bcbf-15e75a29eceb', 'es', '¿Qué acciones pueden subir tu energía antes de acercarte?', '["Mover el cuerpo", "Darle vueltas al resultado", "Aislarte socialmente", "Sonreír a propósito"]'::jsonb, 'Pequeños cambios físicos transforman rápido tu estado interno.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f8818fc9-4dc5-4af7-90ed-aa3dc88ca60d', 'es', 'Estás en espiral pensando en un posible rechazo. ¿En qué podrías concentrarte para ayudarte?', '["En sensaciones inmediatas, como la respiración o los pies en el suelo", "En ensayar respuestas para cada situación posible", "En juzgar tu ansiedad como debilidad"]'::jsonb, 'La realidad física del presente aleja tu atención de los miedos sobre el futuro.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('faacab86-d6dc-4688-a30c-5fa3c018c113', 'es', 'Quieres parecer más receptivo. ¿Qué deberías ajustar primero?', '["Preparar frases de apertura perfectas", "Ensayar halagos", "Esperar a que los demás se acerquen a ti", "Cambiar tu energía a una más positiva y abierta"]'::jsonb, 'La energía positiva invita a los demás a acercarse antes de que digas nada.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ff0646b8-d942-49bb-841f-2415d6f99442', 'es', 'Sostienes la mirada más de lo normal y sale bien. ¿Qué deberías reconocer?', '["Que fue suerte, no una prueba", "Que una sola vez no cuenta", "Una prueba discreta de que puedes confiar en ti en momentos parecidos"]'::jsonb, 'Los pequeños actos suman al historial en el que tu cerebro se apoya para darte seguridad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
